import numpy as np

def make_input(agent_pos, objects, prev=None):
    x = np.zeros((10,10,5), dtype=float)
    x[0,:,3] = 1; x[9,:,3] = 1; x[:,0,3] = 1; x[:,9,3] = 1
    r,c = agent_pos
    x[r,c,0] = 1
    for (r,c,ch) in objects:
        x[r,c,ch] = 1
    if prev is not None:
        for (r,c) in prev:
            x[r,c,4] = 1
    return x.flatten()

agent = (5,5)
scenarios = []
labels = []
scenarios.append(make_input(agent, []))
labels.append('baseline')
directions = {'up':(-1,0), 'down':(1,0), 'left':(0,-1), 'right':(0,1)}
action_idx = {'up':1, 'down':2, 'left':3, 'right':4}
opposite = {'up':'down', 'down':'up', 'left':'right', 'right':'left'}
for ch in [1,2,3]:
    for dname, (dr,dc) in directions.items():
        for dist in [1,2]:
            r = agent[0] + dr*dist
            c = agent[1] + dc*dist
            if 1 <= r <= 8 and 1 <= c <= 8:
                scenarios.append(make_input(agent, [(r,c,ch)]))
                labels.append((ch, dname, dist))
X = np.array(scenarios)
logits = forward(X)
actions = ['noop','up','down','left','right']
print("Baseline logits:", np.round(logits[0],3), "argmax:", actions[np.argmax(logits[0])])
print("ch dir dist | toward_logit away_logit diff | argmax")
for i, lab in enumerate(labels[1:], start=1):
    ch, dname, dist = lab
    toward = action_idx[dname]
    away = action_idx[opposite[dname]]
    diff = logits[i, toward] - logits[i, away]
    am = actions[np.argmax(logits[i])]
    print(f"ch{ch} {dname:5s} d{dist} | {logits[i,toward]:7.3f} {logits[i,away]:7.3f} {diff:7.3f} | {am}")
print("\nAggregate mean (toward - away) by channel:")
for ch in [1,2,3]:
    diffs = []
    for i, lab in enumerate(labels[1:], start=1):
        if lab[0] == ch:
            dname = lab[1]
            toward = action_idx[dname]
            away = action_idx[opposite[dname]]
            diffs.append(logits[i, toward] - logits[i, away])
    print(f"ch{ch}: mean_diff={np.mean(diffs):.3f}")
